  // Inline descriptions
  "vidcfg.durationAutoFromClip": "המשך נקבע אוטומטית מהקליפ המקורי.",
  "vidcfg.wan3Note": "ברירת המחדל היא 5 שניות ב-720p — המדרגה שהערכת הקרדיטים מצטטת. אודיו סביבתי נוצר יחד עם הקליפ. ״אדפטיבי״ מתאים את היחס לקלט המחובר; טקסט-לווידאו בלבד מרונדר ב-16:9 אלא אם נבחר יחס מפורש.",
  "vidcfg.wan3VideoRefLimits": "Wan 3.0 דורש שכל קליפ מקור יהיה באורך 1–15 שניות, שסך כל הקליפים המחוברים לא יעלה על 15 שניות, ושמשך הקלט + משך הפלט יישארו עד 30 שניות. המגבלות נבדקות אצל הספק בזמן הריצה, לא לפני שליחת המשימה.",
  "vidcfg.wan3AudioRefLimits": "כל הפניית אודיו חייבת להיות באורך 1–15 שניות (נבדק לפני שליחת המשימה), וסך כל האודיו המחובר לא יעלה על 15 שניות.",
