  "vidcfg.sameSeedSimilar": "אותו זרע מפיק תוצאות דומות. השאירו ריק לאקראי.",
  "vidcfg.veo31Audio": "VEO 3.1 יוצר אודיו ב-AI מהפרומפט. השביתו לווידאו שקט, ואז השתמשו ברכיב הוספת אודיו.",
  "vidcfg.veoAutoTranslateNote": "הפרומפטים מתורגמים אוטומטית לאנגלית לפני ש-VEO רואה אותם (פעיל כברירת מחדל). השביתו כדי לשמור את הפרומפטים כלשונם — שימושי לפרומפטים שאינם באנגלית או כאשר הניסוח המדויק חשוב (למשל ביטוי החותם ללולאה מושלמת).",
  "vidcfg.veoAutoTranslateNoteShort": "הפרומפטים מתורגמים אוטומטית לאנגלית לפני ש-VEO רואה אותם (פעיל כברירת מחדל). השביתו כדי לשמור את הפרומפטים כלשונם.",
  "vidcfg.worksBestSameFrames": "עובד הכי טוב כאשר פריים ההתחלה והסיום מקובעים לאותה תמונה. ללא פריים סיום, האלגוריתם בוחר את נקודת הלולאה הטובה ביותר שהוא מוצא אך התוצאה עשויה שלא להיות חלקה.",
