  "vidcfg.descSpeechToVideo": "יוצר סרטון דובר מתמונה ואודיו באמצעות Wan 2.2 Speech-to-Video. חברו תמונת דיוקן, אודיו דיבור ופרומפט.",
  "vidcfg.analyzeLeaveBlank": "השאירו ריק וחברו וידאו לנקודת החיבור של הקלט כדי לנתח קליפ שהועלה/נוצר במקום זאת.",
