  "audiocfg.fromConnectedNode": "מרכיב מחובר",
  // Node descriptions
  "audiocfg.descTalkingHeadFaceEnh": "חברו סרטון דובר ורצועת אודיו. כולל שיפור פנים מובנה.",
  "audiocfg.descPortraitTalkingHead": "חברו תמונת דיוקן ורצועת אודיו (דיבור/קריינות) כדי ליצור סרטון דובר.",
  "audiocfg.descSingingDiffusion": "חברו וידאו ורצועת אודיו. הטוב ביותר לשירה — משתמש ב-diffusion לסנכרון שפתיים איכותי.",
  "audiocfg.descFastCheapLipSync": "חברו וידאו או תמונה ורצועת אודיו. סנכרון שפתיים מהיר וזול.",
  "audiocfg.descPortraitNaturalMotion": "חברו תמונת דיוקן ואודיו כדי ליצור דובר עם תנועה טבעית.",
  "audiocfg.descAvatarInference": "חברו וידאו ורצועת אודיו כדי להחליף/לדבב את הדיבור בסנכרון שפתיים מבוסס-אווטאר בדיוק גבוה. החיוב לפי שנייה של פלט.",
  "audiocfg.descStudioGrade": "חברו וידאו (.mp4) ורצועת אודיו (.wav) לסנכרון שפתיים ברמת אולפן. החיוב לפי שנייה של פלט.",
  "audiocfg.descSyncSo": "חברו וידאו ורצועת אודיו כדי לדבב את הצילום עם sync.so v3 (fal.ai). החיוב לפי שנייה של פלט.",
  "audiocfg.descVolcengine": "חברו וידאו ורצועת אודיו כדי לדבב את הצילום (Volcengine). אורך הפלט נקבע לפי האודיו. החיוב לפי שנייה; ~2 קרדיטים לשנייה.",
  "audiocfg.descVoiceExtractor": "מסיר רעשי רקע ומחלץ קול נקי מכל קלט אודיו. חברו מקור אודיו (העלאת אודיו, טקסט לדיבור וכו') לכניסה.",
  "audiocfg.hintSpeakerBoostDesc": "מגביר את מסירת המקור. השאירו על 0 אלא אם רוצים יותר דרמה — ערכים גבוהים מוסיפים השהיה ועלולים להפחית יציבות.",
  "audiocfg.hintSimilarityBoostDesc": "מגביר את הדמיון לקול היעד (משתמש ביותר מחשוב, השהיה קלה). פעיל כברירת מחדל.",
  "audiocfg.hintSeedReproducible": "קיבוע לפלט הניתן לשחזור (אותו זרע + אותו קלט + אותן הגדרות). השאירו ריק לאקראי.",
  "audiocfg.hintDubCloneDesc": "כברירת מחדל הדיבוב משכפל את הדובר המקורי — הוא מדבר בשפת היעד בקולו ובמבטאו. סמנו כאן כדי להשתמש בקול דומה שנשמע מקומי במקום זאת.",
  "audiocfg.hintDubTranslate": "מתרגם את הדיבור לשפת היעד. חברו מקור אודיו לכניסה.",
  "audiocfg.descVoiceDesign": "יוצר קול חדש מתיאור בשפה טבעית ומפיק תצוגה מקדימה של אודיו עם הטקסט שצוין.",
  "audiocfg.descForcedAlign": "מיישר אודיו מול תמלול כדי להפיק חותמות זמן ברמת המילה. חברו מקור אודיו לכניסה.",
  "audiocfg.descRecast1": "הדוברים מזוהים אוטומטית. קול 1 מחליף את הדובר הראשון, קול 2 את",
  "audiocfg.descRecast2": "השני, וכן הלאה. דוברים מעבר לסוף הרשימה שומרים על קולם המקורי.",
  "audiocfg.hintPreservedMusicLevel": "קובע את עוצמת מוזיקת הרקע הנשמרת ביחס לקולות שהוחלפו.",
  // Multi-line helper paragraphs
  "audiocfg.hintRevoiceOffOn": "כבוי: שמירת מצע המוזיקה / האפקטים מתחת לקול החדש. פועל: פלט נקי, קול בלבד.",
  "audiocfg.hintRevoicePre": "מחליף את הקול בקול הנבחר תוך שמירה על הרגש, המקצב והתזמון. חברו ",
  "audiocfg.hintRevoiceMid": " בכניסה לפלט אודיו, או ",
  "audiocfg.hintRevoicePost": " בכניסה כדי להחליף קול לקליפ דיבור שלם (מקבלים בחזרה את הווידאו בתוספת רצועת האודיו החדשה). אם שניהם מחוברים, הווידאו גובר וקלט האודיו מתעלם.",
